      this.descripcion = data.Descripcion;
      this.codigoimpuesto = data.CodigImpuesto;
      this.stock = data.StockActual;
      this.precio = data.PrecioVentaMinorista;
      this.close();
    },
    limpiarDatosRepuesto: function limpiarDatosRepuesto() {
      this.descripcion = '';
      this.cantidad = '';
      this.precio = '';
      this.stock = '';
    },
    agregarNuevo: function agregarNuevo() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      console.log(this.$store.state.usuario);
      axios.post('orden/insertardetalle', {
        'CodigoSucursal': this.$store.state.usuario.CodigoSucursal,
        'PuntoExpedicion': this.$store.state.usuario.PuntoExpedicion,
        'numero': this.codigorecepcion,
        'codigoestadoorden': this.capturarcodigo(this.orden),
        'observacion': this.avisorden,
        'codigoproducto': this.codigoproducto,
        'mecanico': this.mecanico,
        'codigomecanico': this.capturarcodigo(this.mecanico),
        'codigoimpuesto': this.codigoimpuesto,
        'orden': this.orden,
        'descripcion': this.descripcion,
        'cantidad': this.cantidad,
        'precio': this.precio
      }, configuracion).then(function (response) {// me.limpiarDetalle();
      }).catch(function (error) {
        console.log(error);
      });
    },
    agregarTabla: function agregarTabla() {
      this.errorArticulo = null;

      if (this.codigoproducto == '') {
        this.errorArticulo = 'DEBE DE SELECCIONAR UN REPUESTO';
        return;
      }

      if (this.encuentra(this.codigoproducto) == true) {
        this.errorArticulo = 'El artículo ya ha sido agregado.';
      } else {
        if (this.bandera == 1) {
          this.agregarNuevo();
          this.detalles.push({
            codigoproducto: this.codigoproducto,
            mecanico: this.mecanico,
            codigomecanico: this.capturarcodigo(this.mecanico),
            codigoimpuesto: this.codigoimpuesto,
            orden: this.orden,
            descripcion: this.descripcion,
            cantidad: this.cantidad,
            precio: this.precio
          });
        } else {
          {
            this.detalles.push({
              codigoproducto: this.codigoproducto,
              mecanico: this.mecanico,
              codigomecanico: this.capturarcodigo(this.mecanico),
              codigoimpuesto: this.codigoimpuesto,
              orden: this.orden,
              descripcion: this.descripcion,
              cantidad: this.cantidad,
              precio: this.precio
            });
            this.limpiarDetalle();
          }
        }
      }

      console.log(this.detalles);
      this.limpiarDatosRepuesto();
    },
    encuentra: function encuentra(codigoproducto) {
      var sw = 0;

      for (var i = 0; i < this.detalles.length; i++) {
        if (this.detalles[i].codigoproducto == codigoproducto) {
          sw = true;
        }
      }

      return sw;
    },
    eliminarDetalle: function eliminarDetalle(arr, item) {
      if (this.bandera == 1) {
        var me = this;
        var header = {
          "auth-token": this.$store.state.token
        };
        var configuracion = {
          headers: header
        };
        axios.put('orden/eliminar', {
          'codigoproducto': item.codigoproducto,
          'cantidad': item.cantidad,
          'codigorecepcion': this.codigorecepcion
        }, configuracion).then(function (response) {}).catch(function (error) {
          console.log(error);
        });
      }

      var i = arr.indexOf(item);

      if (i != -1) {
        arr.splice(i, 1);
      }
    },
    listarRecepcion: function listarRecepcion() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('orden/recepcion', configuracion).then(function (response) {
        me.recepciones = response.data;
        console.log(me.recepciones);
      }).catch(function (error) {
        console.log(error);
