    editar: function editar(item) {
      this.bandera = 1;
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('orden/update/' + item.numero, configuracion).then(function (response) {
        me.detalles = response.data;

        for (var i in me.detalles) {
          me.chapa = me.detalles[i].numerochapa;
          me.codigorecepcion = me.detalles[i].numero;
          me.orden = me.detalles[i].estadorden;
          me.mecanico = me.detalles[i].mecanico;
          me.avisorden = me.detalles[i].observacion;
          me.observacion = me.detalles[i].observaciones; // console.log(me.cliente)
        }

        me.mostrarNuevo();
      }).catch(function (error) {
        console.log(error);
      });
    },
    mostrarModalArticulos: function mostrarModalArticulos() {
      this.dialog = 1;
      this.listarRecepcion();
    },
    mostrarModalRepuestos: function mostrarModalRepuestos() {
      this.dialogrepuestos = 1;
      this.listarRepuesto();
    },
    listarDetalles: function listarDetalles() {
      console.log("cliente 2");
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };

      cliente: this.cliente;

      console.log(cliente);
      axios.get('rvehiculo/' + cliente, configuracion).then(function (response) {
        me.detalles = response.data.detalles;
      }).catch(function (error) {
        console.log(error);
      });
    },
    verIngreso: function verIngreso(item) {
      this.limpiar();
      this.tipo_comprobante = item.tipo_comprobante;
      this.serie_comprobante = item.serie_comprobante;
      this.num_comprobante = item.num_comprobante;
      this.persona = item.persona._id;
      this.impuesto = item.impuesto;
      this.listarDetalles();
      this.verNuevo = 1;
      this.verDetalle = 1;
    },
    entregado: function entregado(item) {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      this.numero = item.numero;
      console.log(this.numero);
      axios.put("orden/entregado", {
        numero: this.numero
      }, configuracion).then(function (response) {
        me.listar();
      }).catch(function (error) {
        console.log(error);
        console.log("error");
      });
    },
    listar: function listar() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('orden/listar/', configuracion).then(function (response) {
        me.ventas = response.data;
        console.log(me.ventas);
      }).catch(function (error) {
        console.log(error);
      });
    },
    limpiarDetalle: function limpiarDetalle() {
      this.codigoimpuesto = '';
      this.codigoproducto = '';
      this.stock = '';
      this.precio = '';
      this.cantidad = '';
      this.descripcion = '';
      this.validaMensaje = [];
      this.verDetalle = 0;
    },
    limpiarTodo: function limpiarTodo() {
      this.recepcion = "";
      this.observacion = '';
      this.codigorecepcion = "";
      this.chapa = "";
      this.orden = "";
      this.mecanico = '';
      this.avisorden = '';
      this.codigoimpuesto = '';
      this.codigoproducto = '';
      this.stock = '';
      this.precio = '';
      this.cantidad = '';
      this.repuesto = '';
      this.descripcion = '';
      this.detalles = [];
      this.validaMensaje = [];
      this.verDetalle = 0;
    },
    validar: function validar() {
      this.valida = 0;
      this.validaMensaje = [];

      if (!this.persona) {
        this.validaMensaje.push('Seleccione un cliente.');
      }

      if (!this.tipo_comprobante) {
        this.validaMensaje.push('Seleccione un tipo de comprobante.');
      }

      if (!this.num_comprobante) {
        this.validaMensaje.push('Ingrese el número del comprobante.');
      }

      if (!this.impuesto || this.impuesto < 0 || this.impuesto > 1) {
        this.validaMensaje.push('Ingrese un impuesto válido.');
      }

      if (this.detalles.length <= 0) {
        this.validaMensaje.push('Ingrese al menos un artículo al detalle');
      }

      if (this.validaMensaje.length) {
        this.valida = 1;
      }

      return this.valida;
    },
    mostrarNuevo: function mostrarNuevo() {
      this.verNuevo = 1;
    },
    ocultarNuevo: function ocultarNuevo() {
      this.verNuevo = 0;
      this.bandera = 0;
      this.listar();
      this.limpiarTodo();
    },
    guardar: function guardar() {
      if (this.bandera == 0) {
        var me = this;
        var header = {
          "auth-token": this.$store.state.token
        };
        var configuracion = {
          headers: header
        };
        console.log(this.$store.state.usuario);
        axios.post('orden/guardar', {
          'CodigoSucursal': this.$store.state.usuario.CodigoSucursal,
          'PuntoExpedicion': this.$store.state.usuario.PuntoExpedicion,
          'numero': this.codigorecepcion,
          'codigoestadoorden': this.capturarcodigo(this.orden),
          'observacion': this.avisorden,
          'detalles': this.detalles
        }, configuracion).then(function (response) {
          me.dialogoConfirmacion = true;
          me.limpiarDetalle();
          me.limpiarTodo();
          me.close();
          me.listar();
          me.ocultarNuevo();
        }).catch(function (error) {
          console.log(error);
        });
      } else {
        this.ocultarNuevo();
        console.log("es una modificacion");
      }
    },
    activarDesactivarMostrar: function activarDesactivarMostrar(accion, item) {
      this.adModal = 1;
      this.adNombre = item.num_comprobante;
      this.adId = item._id;

      if (accion == 1) {
        this.adAccion = 1;
      } else if (accion == 2) {
        this.adAccion = 2;
      } else {
        this.adModal = 0;
      }
    },
    activarDesactivarCerrar: function activarDesactivarCerrar() {
      this.adModal = 0;
    },
    close: function close() {
      this.dialog = false;
      this.dialogrepuestos = false;
    }
  }
};
